export async function retry(operation, options = {}) {
  const { maxAttempts, delayMs, sleep } = options;

  if (typeof operation !== 'function') {
    throw new TypeError('retry: operation must be a function');
  }
  if (!Number.isInteger(maxAttempts) || maxAttempts < 1) {
    throw new RangeError('retry: maxAttempts must be an integer >= 1');
  }
  if (maxAttempts > 1 && typeof sleep !== 'function') {
    throw new TypeError('retry: sleep must be a function');
  }

  let lastError;
  for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {
    try {
      return await operation(attempt);
    } catch (error) {
      lastError = error;
      if (attempt < maxAttempts) {
        await sleep(delayMs);
      }
    }
  }

  throw lastError;
}

